    /**
     * Method to retrieve the Branch via BranchFetchOneSummary
     * @param 	summary BranchFetchOneSummary 
     * @return 	BranchFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Branch getBranch( BranchFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "BranchFetchOneSummary arg cannot be null" );
    	
    	Branch entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Branch
        	// --------------------------------------
        	CompletableFuture<Branch> futureEntity = queryGateway.query(new FindBranchQuery( new LoadBranchFilter( summary.getBranchId() ) ), ResponseTypes.instanceOf(Branch.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Branch with id " + summary.getBranchId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


